// 伤寒论（宋本）398 条全文 + 白话解释
// 字段：id 序号 / chapter 篇名 / category 六经大类 / text 原文 / explain 白话解释
const SHLH_DATA = [
  // ========== 辨太阳病脉证并治（上）第 1-30 条 ==========
  {id:1, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳之为病，脉浮，头项强痛而恶寒。", explain:"太阳病的总纲：脉象浮，头项部僵硬疼痛，并且怕冷。"},
  {id:2, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，发热，汗出，恶风，脉缓者，名为中风。", explain:"太阳病中出现发热、出汗、怕风、脉象缓和的，称为中风（表虚证）。"},
  {id:3, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名为伤寒。", explain:"太阳病中，无论是否已发热，一定怕冷、身体疼痛、呕逆、寸关尺脉都紧的，称为伤寒（表实证）。"},
  {id:4, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"伤寒一日，太阳受之，脉若静者，为不传；颇欲吐，若躁烦，脉数急者，为传也。", explain:"伤寒第一天太阳受病，脉象平和说明不传变；若很想吐、躁烦、脉数急，说明要传变。"},
  {id:5, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"伤寒二三日，阳明、少阳证不见者，为不传也。", explain:"伤寒两三天仍不见阳明、少阳证候的，说明病不传变。"},
  {id:6, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，鼻息必鼾，语言难出。若被下者，小便不利，直视失溲；若被火者，微发黄色，剧则如惊痫，时瘛疭，若火熏之。一逆尚引日，再逆促命期。", explain:"太阳病发热口渴而不怕冷的是温病；发汗后身灼热的叫风温。误用攻下或火法会加重，一误尚可拖延时日，再误则危及生命。"},
  {id:7, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳，七日愈；发于阴，六日愈。以阳数七，阴数六故也。", explain:"发热怕冷的是发于阳，无热怕冷的是发于阴；发于阳七天愈，发于阴六天愈，因阳数为七、阴数为六。"},
  {id:8, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，头痛至七日以上自愈者，以行其经尽故也。若欲作再经者，针足阳明，使经不传则愈。", explain:"太阳病头痛七天以上自愈，是太阳经行尽之故；若将传他经，针刺足阳明以阻断传变即愈。"},
  {id:9, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，欲解时，从巳至未上。", explain:"太阳病将要缓解的时间，在巳时到未时（上午9点到下午3点）之间。"},
  {id:10, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"风家，表解而不了了者，十二日愈。", explain:"常患中风的人，表证虽解但精神不爽利的，约十二天可痊愈。"},
  {id:11, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"病人身大热，反欲得衣者，热在皮肤，寒在骨髓也；身大寒，反不欲近衣者，寒在皮肤，热在骨髓也。", explain:"身体大热却想加衣，是真寒假热；身体大寒却不想穿衣，是真热假寒。"},
  {id:12, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳中风，阳浮而阴弱，阳浮者，热自发；阴弱者，汗自出。啬啬恶寒，淅淅恶风，翕翕发热，鼻鸣干呕者，桂枝汤主之。", explain:"太阳中风，脉浮缓、阵阵怕冷怕风、微微发热、鼻鸣干呕的，用桂枝汤治疗。"},
  {id:13, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，头痛，发热，汗出，恶风，桂枝汤主之。", explain:"太阳病见头痛、发热、出汗、怕风的，用桂枝汤治疗。"},
  {id:14, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，项背强几几，反汗出恶风者，桂枝加葛根汤主之。", explain:"太阳病项背强硬、反而出汗怕风的，用桂枝加葛根汤治疗。"},
  {id:15, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，下之后，其气上冲者，可与桂枝汤，方用前法；若不上冲者，不得与之。", explain:"太阳病攻下后，仍有气上冲的可用桂枝汤；若无气上冲则不可用。"},
  {id:16, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病三日，已发汗，若吐、若下、若温针，仍不解者，此为坏病，桂枝不中与之也。观其脉证，知犯何逆，随证治之。桂枝本为解肌，若其人脉浮紧，发热汗不出者，不可与之也。常须识此，勿令误也。", explain:"太阳病误治后病不解成为坏病，不能再用桂枝汤，应观脉证、辨明误治随证治疗。脉浮紧无汗的表实证禁用桂枝汤。"},
  {id:17, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"若酒客病，不可与桂枝汤，得之则呕，以酒客不喜甘故也。", explain:"嗜酒的人患太阳病不可用桂枝汤，服后会呕吐，因酒客不喜甘味。"},
  {id:18, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"喘家作，桂枝汤加厚朴、杏子佳。", explain:"平素患喘病的人发作，用桂枝汤加厚朴、杏仁为好。"},
  {id:19, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"凡服桂枝汤吐者，其后必吐脓血也。", explain:"凡服桂枝汤后呕吐的人，以后会吐脓血。"},
  {id:20, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，发汗，遂漏不止，其人恶风，小便难，四肢微急，难以屈伸者，桂枝加附子汤主之。", explain:"太阳病发汗太过，汗出不止、怕风、小便难、四肢拘急屈伸不利的，用桂枝加附子汤治疗。"},
  {id:21, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，下之后，脉促，胸满者，桂枝去芍药汤主之。", explain:"太阳病攻下后脉促、胸闷的，用桂枝去芍药汤治疗。"},
  {id:22, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"若微恶寒者，桂枝去芍药加附子汤主之。", explain:"若又出现轻微怕冷的，用桂枝去芍药加附子汤治疗。"},
  {id:23, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，得之八九日，如疟状，发热恶寒，热多寒少，其人不呕，清便欲自可，一日二三度发。脉微缓者，为欲愈也；脉微而恶寒者，此阴阳俱虚，不可更发汗、更下、更吐也；面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜桂枝麻黄各半汤。", explain:"太阳病八九日，如疟疾样发热恶寒、热多寒少、一日发作两三次，脉微缓是欲愈；脉微而恶寒是阴阳俱虚不可再汗下吐；面色有热色、身痒者是未解，宜桂枝麻黄各半汤。"},
  {id:24, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，初服桂枝汤，反烦不解者，先刺风池、风府，却与桂枝汤则愈。", explain:"太阳病初服桂枝汤反而心烦不解的，先刺风池、风府，再服桂枝汤则愈。"},
  {id:25, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"服桂枝汤，大汗出，脉洪大者，与桂枝汤，如前法；若形似疟，一日再发者，汗出必解，宜桂枝二麻黄一汤。", explain:"服桂枝汤大汗出脉洪大，仍按桂枝汤法；若如疟状一日再发，宜桂枝二麻黄一汤。"},
  {id:26, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"服桂枝汤，大汗出后，大烦渴不解，脉洪大者，白虎加人参汤主之。", explain:"服桂枝汤大汗出后大烦渴不解、脉洪大的，用白虎加人参汤治疗。"},
  {id:27, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不可发汗，宜桂枝二越婢一汤。", explain:"太阳病发热恶寒热多寒少，脉微弱说明阳气不足，不可发汗，宜桂枝二越婢一汤。"},
  {id:28, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"服桂枝汤，或下之，仍头项强痛，翕翕发热，无汗，心下满微痛，小便不利者，桂枝去桂加茯苓白术汤主之。", explain:"服桂枝汤或攻下后仍头项强痛、发热无汗、心下满微痛、小便不利的，用桂枝去桂加茯苓白术汤治疗。"},
  {id:29, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"伤寒，脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，反与桂枝，欲攻其表，此误也。得之便厥，咽中干，烦躁吐逆者，作甘草干姜汤与之，以复其阳；若厥愈足温者，更作芍药甘草汤与之，其脚即伸；若胃气不和，谵语者，少与调胃承气汤；若重发汗，复加烧针者，四逆汤主之。", explain:"伤寒脉浮、自汗、小便数、心烦、微恶寒、脚抽筋的，误用桂枝汤攻表是错的。误治后厥冷咽干烦躁吐逆用甘草干姜汤复阳；厥愈足温后用芍药甘草汤伸脚；胃气不和谵语用少量调胃承气汤；重发汗加烧针的用四逆汤。"},
  {id:30, chapter:"辨太阳病脉证并治（上）", category:"太阳病", text:"问曰：证象阳旦，按法治之而增剧，厥逆，咽中干，两胫拘急而谵语。师曰：言夜半手足当温，两脚当伸。后如师言。何以知此？答曰：寸口脉浮而大，浮为风，大为虚，风则生微热，虚则两胫挛。病形象桂枝，因加附子参其间，增桂令汗出，附子温经，亡阳故也。厥逆咽中干，烦躁，阳明内结，谵语烦乱，更饮甘草干姜汤，夜半阳气还，两足当热，胫尚微拘急，重与芍药甘草汤，尔乃胫伸。以承气汤微溏，则止其谵语，故知病可愈。", explain:"此条解释上条证象阳旦却加重的原因，并说明用甘草干姜汤、芍药甘草汤、承气汤依次救误的过程与机理。"},

  // ========== 辨太阳病脉证并治（中）第 31-127 条 ==========
  {id:31, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，项背强几几，无汗恶风，葛根汤主之。", explain:"太阳病项背强硬、无汗怕风的，用葛根汤治疗。"},
  {id:32, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳与阳明合病者，必自下利，葛根汤主之。", explain:"太阳与阳明合病，必然下利的，用葛根汤治疗。"},
  {id:33, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳与阳明合病，不下利，但呕者，葛根加半夏汤主之。", explain:"太阳阳明合病，不下利而呕吐的，用葛根加半夏汤治疗。"},
  {id:34, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，桂枝证，医反下之，利遂不止，脉促者，表未解也；喘而汗出者，葛根黄芩黄连汤主之。", explain:"桂枝证误下后下利不止、脉促是表未解；喘而汗出的，用葛根黄芩黄连汤治疗。"},
  {id:35, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，头痛发热，身疼腰痛，骨节疼痛，恶风，无汗而喘者，麻黄汤主之。", explain:"太阳病头痛发热、身疼腰痛、骨节疼痛、怕风无汗而喘的，用麻黄汤治疗。"},
  {id:36, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳与阳明合病，喘而胸满者，不可下，宜麻黄汤。", explain:"太阳阳明合病，气喘胸闷的不可攻下，宜用麻黄汤。"},
  {id:37, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，十日已去，脉浮细而嗜卧者，外已解也。设胸满胁痛者，与小柴胡汤；脉但浮者，与麻黄汤。", explain:"太阳病十余日，脉浮细嗜卧是外证已解；胸满胁痛给小柴胡汤；脉只浮的给麻黄汤。"},
  {id:38, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳中风，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，大青龙汤主之。若脉微弱，汗出恶风者，不可服之。服之则厥逆，筋惕肉瞤，此为逆也。", explain:"太阳中风脉浮紧、发热恶寒、身痛、无汗而烦躁的，用大青龙汤；若脉微弱、汗出怕风则禁用，误服会厥逆、筋肉跳动。"},
  {id:39, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，大青龙汤发之。", explain:"伤寒脉浮缓、身不痛但重、时轻时重、无少阴证的，用大青龙汤发散。"},
  {id:40, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒表不解，心下有水气，干呕发热而咳，或渴，或利，或噎，或小便不利、少腹满，或喘者，小青龙汤主之。", explain:"伤寒表证未解、心下停水，干呕发热咳嗽，或兼渴、下利、噎、小便不利、喘的，用小青龙汤治疗。"},
  {id:41, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒，心下有水气，咳而微喘，发热不渴。服汤已渴者，此寒去欲解也。小青龙汤主之。", explain:"伤寒心下停水，咳嗽微喘发热不渴，服小青龙汤后口渴是寒去欲解的征象。"},
  {id:42, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，外证未解，脉浮弱者，当以汗解，宜桂枝汤。", explain:"太阳病外证未解、脉浮弱的，应当发汗解表，宜用桂枝汤。"},
  {id:43, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，下之微喘者，表未解故也，桂枝加厚朴杏子汤主之。", explain:"太阳病攻下后轻微气喘，是表证未解，用桂枝加厚朴杏子汤治疗。"},
  {id:44, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，外证未解，不可下也，下之为逆。欲解外者，宜桂枝汤。", explain:"太阳病外证未解不可攻下，攻下是逆治，想解表的宜用桂枝汤。"},
  {id:45, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故在外，当须解外则愈，宜桂枝汤。", explain:"太阳病先发汗不解又误下，脉浮仍不愈，因浮主表，应当解表，宜桂枝汤。"},
  {id:46, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，脉浮紧，无汗，发热，身疼痛，八九日不解，表证仍在，此当发其汗。服药已微除，其人发烦目瞑，剧者必衄，衄乃解。所以然者，阳气重故也。麻黄汤主之。", explain:"太阳病脉浮紧无汗身痛八九日不解，表证仍在应当发汗；服药后微解，烦躁闭目，重者鼻衄，衄后病解，是阳气郁重之故，用麻黄汤。"},
  {id:47, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，脉浮紧，发热，身无汗，自衄者愈。", explain:"太阳病脉浮紧发热无汗，自然鼻衄的病可愈。"},
  {id:48, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"二阳并病，太阳初得病时，发其汗，汗先出不彻，因转属阳明，续自微汗出，不恶寒。若太阳病证不罢者，不可下，下之为逆，如此可小发汗。设面色缘缘正赤者，阳气怫郁在表，当解之熏之；若发汗不彻，不足言，阳气怫郁不得越，当汗不汗，其人躁烦，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气但坐，以汗出不彻故也，更发汗则愈。何以知汗出不彻？以脉涩故知也。", explain:"太阳、阳明并病，发汗不彻底而转属阳明；太阳证未罢不可攻下，可小发其汗。面色红赤是阳气郁在表，须解表熏蒸；汗出不彻会躁烦、痛无定处、短气，再发汗则愈。"},
  {id:49, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"脉浮数者，法当汗出而愈。若下之，身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚，须表里实，津液自和，便自汗出愈。", explain:"脉浮数本应发汗而愈；若误下后身重心悸、尺脉微，是里虚，不可发汗，待里气实、津液自和则自汗出愈。"},
  {id:50, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以知然？以荣气不足，血少故也。", explain:"脉浮紧身痛应当发汗解表；若尺脉迟，是营血不足，不可发汗。"},
  {id:51, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"脉浮者，病在表，可发汗，宜麻黄汤。", explain:"脉浮说明病在表，可以发汗，宜用麻黄汤。"},
  {id:52, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"脉浮而数者，可发汗，宜麻黄汤。", explain:"脉浮而数的，可以发汗，宜用麻黄汤。"},
  {id:53, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"病常自汗出，此为荣气和。荣气和者，外不谐，以卫气不共荣气谐和故尔。以荣行脉中，卫行脉外，复发其汗，荣卫和则愈。宜桂枝汤。", explain:"时常自汗出是卫气不与营气谐和，用桂枝汤调和营卫则愈。"},
  {id:54, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜桂枝汤。", explain:"内脏无病而定时发热自汗的，是卫气不和，在发热前服桂枝汤发汗则愈。"},
  {id:55, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒脉浮紧，不发汗，因致衄者，麻黄汤主之。", explain:"伤寒脉浮紧未发汗而致鼻衄的，仍用麻黄汤治疗。"},
  {id:56, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒不大便六七日，头痛有热者，与承气汤。其小便清者，知不在里，仍在表也，当须发汗。若头痛者必衄。宜桂枝汤。", explain:"伤寒六七日不大便、头痛发热，小便清说明病在表不在里，应当发汗，宜桂枝汤；头痛的可能鼻衄。"},
  {id:57, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒发汗已解，半日许复烦，脉浮数者，可更发汗，宜桂枝汤。", explain:"伤寒发汗已解，半日后又烦、脉浮数，可再发汗，宜桂枝汤。"},
  {id:58, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"凡病若发汗、若吐、若下、若亡血、亡津液，阴阳自和者，必自愈。", explain:"凡病经汗吐下或失血失津液后，只要阴阳自和，必能自愈。"},
  {id:59, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"大下之后，复发汗，小便不利者，亡津液故也。勿治之，得小便利，必自愈。", explain:"大下后又发汗、小便不利，是津液耗伤，不必治疗，小便恢复即自愈。"},
  {id:60, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"下之后，复发汗，必振寒，脉微细。所以然者，以内外俱虚故也。", explain:"攻下后又发汗，必振寒、脉微细，是内外俱虚之故。"},
  {id:61, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"下之后，复发汗，昼日烦躁不得眠，夜而安静，不呕不渴，无表证，脉沉微，身无大热者，干姜附子汤主之。", explain:"攻下后发汗，白天烦躁不得眠、夜间安静、不呕不渴无表证、脉沉微身无大热的，用干姜附子汤治疗。"},
  {id:62, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗后，身疼痛，脉沉迟者，桂枝加芍药生姜各一两人参三两新加汤主之。", explain:"发汗后身疼痛、脉沉迟的，用桂枝新加汤治疗。"},
  {id:63, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗后，不可更行桂枝汤，汗出而喘，无大热者，可与麻黄杏仁甘草石膏汤。", explain:"发汗后汗出而喘、无大热，不可再用桂枝汤，用麻杏甘石汤。"},
  {id:64, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。", explain:"发汗过多，心阳虚而心悸、喜用手按的，用桂枝甘草汤治疗。"},
  {id:65, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗后，其人脐下悸者，欲作奔豚，茯苓桂枝甘草大枣汤主之。", explain:"发汗后脐下跳动、将要发作奔豚的，用苓桂甘枣汤治疗。"},
  {id:66, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗后，腹胀满者，厚朴生姜半夏甘草人参汤主之。", explain:"发汗后腹胀满的，用厚朴生姜半夏甘草人参汤治疗。"},
  {id:67, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒若吐、若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，茯苓桂枝白术甘草汤主之。", explain:"伤寒吐下后心下逆满、气上冲胸、起身头眩、脉沉紧的，用苓桂术甘汤治疗；不可发汗以免动经身摇。"},
  {id:68, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗，病不解，反恶寒者，虚故也，芍药甘草附子汤主之。", explain:"发汗后病不解反而怕冷，是阳虚之故，用芍药甘草附子汤治疗。"},
  {id:69, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗，若下之，病仍不解，烦躁者，茯苓四逆汤主之。", explain:"发汗或攻下后病不解、烦躁的，用茯苓四逆汤治疗。"},
  {id:70, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗后，恶寒者，虚故也；不恶寒，但热者，实也，当和胃气，与调胃承气汤。", explain:"发汗后怕冷是虚；不怕冷而发热是实，当调和胃气，用调胃承气汤。"},
  {id:71, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水者，少少与饮之，令胃气和则愈。若脉浮，小便不利，微热消渴者，五苓散主之。", explain:"发汗后胃中干燥、烦躁想饮水，少量给水使胃气调和即愈；若脉浮、小便不利、微热口渴的，用五苓散。"},
  {id:72, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗已，脉浮数，烦渴者，五苓散主之。", explain:"发汗后脉浮数、烦渴的，用五苓散治疗。"},
  {id:73, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒，汗出而渴者，五苓散主之；不渴者，茯苓甘草汤主之。", explain:"伤寒汗出而口渴的用五苓散，不渴的用茯苓甘草汤。"},
  {id:74, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆，五苓散主之。", explain:"中风发热六七日不解而烦，渴欲饮水却水入即吐的，叫水逆，用五苓散治疗。"},
  {id:75, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"未持脉时，病人手叉自冒心，师因教试令咳，而不咳者，此必两耳聋无闻也。所以然者，以重发汗，虚故如此。发汗后，饮水多必喘，以水灌之亦喘。", explain:"重发汗导致耳聋；发汗后饮水过多或用冷水浇灌，都会气喘。"},
  {id:76, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗后，水药不得入口，为逆。若更发汗，必吐下不止。发汗吐下后，虚烦不得眠，若剧者，必反复颠倒，心中懊憹，栀子豉汤主之；若少气者，栀子甘草豉汤主之；若呕者，栀子生姜豉汤主之。", explain:"发汗后水药不能入口是逆证；发汗吐下后虚烦不得眠、心中懊憹的用栀子豉汤，少气的加甘草，呕吐的加生姜。"},
  {id:77, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"发汗若下之，而烦热胸中窒者，栀子豉汤主之。", explain:"发汗或攻下后烦热、胸中窒闷的，用栀子豉汤治疗。"},
  {id:78, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒五六日，大下之后，身热不去，心中结痛者，未欲解也，栀子豉汤主之。", explain:"伤寒五六日大下后身热不退、心中结痛的，病未解，用栀子豉汤。"},
  {id:79, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒下后，心烦腹满，卧起不安者，栀子厚朴汤主之。", explain:"伤寒攻下后心烦腹满、坐卧不安的，用栀子厚朴汤治疗。"},
  {id:80, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒，医以丸药大下之，身热不去，微烦者，栀子干姜汤主之。", explain:"伤寒用丸药大下后身热不退、微烦的，用栀子干姜汤治疗。"},
  {id:81, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"凡用栀子汤，病人旧微溏者，不可与服之。", explain:"凡用栀子汤，平素大便微溏的不可服用。"},
  {id:82, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病发汗，汗出不解，其人仍发热，心下悸，头眩，身瞤动，振振欲擗地者，真武汤主之。", explain:"太阳病发汗后汗出不解、仍发热、心下悸、头眩、身体颤动欲倒的，用真武汤治疗。"},
  {id:83, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"咽喉干燥者，不可发汗。", explain:"咽喉干燥的，不可发汗。"},
  {id:84, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"淋家，不可发汗，发汗必便血。", explain:"久患淋证的人不可发汗，发汗必尿血。"},
  {id:85, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"疮家，虽身疼痛，不可发汗，发汗则痉。", explain:"久患疮疡的人，虽身痛也不可发汗，发汗会致痉。"},
  {id:86, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"衄家，不可发汗，汗出必额上陷，脉急紧，直视不能眴，不得眠。", explain:"常鼻衄的人不可发汗，发汗会额部陷下、脉紧、直视不能转、不得眠。"},
  {id:87, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"亡血家，不可发汗，发汗则寒栗而振。", explain:"失血的人不可发汗，发汗会寒战振栗。"},
  {id:88, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"汗家，重发汗，必恍惚心乱，小便已阴疼，与禹余粮丸。", explain:"常出汗的人再发汗，会神志恍惚心乱、小便后阴痛，用禹余粮丸。"},
  {id:89, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"病人有寒，复发汗，胃中冷，必吐蛔。", explain:"病人本有寒，再发汗会胃中冷，必吐蛔虫。"},
  {id:90, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"本发汗，而复下之，此为逆也；若先发汗，治不为逆。本先下之，而反汗之，为逆；若先下之，治不为逆。", explain:"本应发汗却攻下是逆治，先发汗才是顺治；本应攻下却发汗也是逆治。"},
  {id:91, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒，医下之，续得下利清谷不止，身疼痛者，急当救里；后身疼痛，清便自调者，急当救表。救里宜四逆汤，救表宜桂枝汤。", explain:"伤寒误下后下利清谷不止、身痛，应先救里用四逆汤；里和后再救表用桂枝汤。"},
  {id:92, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"病发热头痛，脉反沉，若不差，身体疼痛，当救其里，宜四逆汤。", explain:"发热头痛而脉反沉，若病不愈身痛，当救里，宜四逆汤。"},
  {id:93, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，先下而不愈，因复发汗，以此表里俱虚，其人因致冒，冒家汗出自愈。所以然者，汗出表和故也。里未和，然后复下之。", explain:"太阳病先下后汗致表里俱虚而头昏冒，冒家自汗出即愈，因汗出表和；里未和再攻下。"},
  {id:94, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病未解，脉阴阳俱停，必先振栗，汗出而解。但阳脉微者，先汗出而解；但阴脉微者，下之而解。若欲下之，宜调胃承气汤。", explain:"太阳病未解、寸关尺脉伏而不显，必先振栗汗出而解；阳脉微的汗解，阴脉微的下解，宜调胃承气汤。"},
  {id:95, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，发热汗出者，此为荣弱卫强，故使汗出。欲救邪风者，宜桂枝汤。", explain:"太阳病发热汗出是营弱卫强，想解肌祛风宜用桂枝汤。"},
  {id:96, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒五六日中风，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞硬，或心下悸、小便不利，或不渴、身有微热，或咳者，小柴胡汤主之。", explain:"伤寒五六日见往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕的，用小柴胡汤；此为少阳证主方。"},
  {id:97, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"血弱气尽，腠理开，邪气因入，与正气相搏，结于胁下。正邪分争，往来寒热，休作有时，嘿嘿不欲饮食。脏腑相连，其痛必下，邪高痛下，故使呕也，小柴胡汤主之。服柴胡汤已，渴者属阳明，以法治之。", explain:"气血虚弱、腠理开、邪气入里结于胁下，正邪相争出现往来寒热、默默不欲饮食、呕的，用小柴胡汤；服后口渴转属阳明，按阳明法治疗。"},
  {id:98, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"得病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，而胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤，后必下重。本渴饮水而呕者，柴胡不中与也，食谷者哕。", explain:"脉迟浮弱、恶风寒、手足温而误下后不能食、胁下满痛、发黄、小便难的，用柴胡汤会下重；本渴饮水而呕者不可用柴胡汤。"},
  {id:99, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒四五日，身热恶风，颈项强，胁下满，手足温而渴者，小柴胡汤主之。", explain:"伤寒四五日，身热恶风、颈项强、胁下满、手足温而渴的，用小柴胡汤。"},
  {id:100, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与小建中汤；不差者，小柴胡汤主之。", explain:"伤寒阳脉涩阴脉弦，本当腹中急痛，先用小建中汤，不愈再用小柴胡汤。"},
  {id:101, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒中风，有柴胡证，但见一证便是，不必悉具。凡柴胡汤病证而下之，若柴胡证不罢者，复与柴胡汤，必蒸蒸而振，却发热汗出而解。", explain:"伤寒中风只要见一个柴胡证即可用小柴胡汤，不必诸证具备；误下后柴胡证仍在，再服会战汗而解。"},
  {id:102, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒二三日，心中悸而烦者，小建中汤主之。", explain:"伤寒二三日，心中悸动而烦的，用小建中汤治疗。"},
  {id:103, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与小柴胡汤。呕不止，心下急，郁郁微烦者，为未解也，与大柴胡汤下之则愈。", explain:"太阳病过经十余日误下后柴胡证仍在，先给小柴胡汤；若呕不止、心下急、郁郁微烦，是未解，用大柴胡汤攻下则愈。"},
  {id:104, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒十三日不解，胸胁满而呕，日晡所发潮热，已而微利。此本柴胡证，下之以不得利，今反利者，知医以丸药下之，此非其治也。潮热者，实也。先宜服小柴胡汤以解外，后以柴胡加芒硝汤主之。", explain:"伤寒十三日不解，胸胁满呕、日晡潮热而微利，本属柴胡证，医误用丸药攻下；先服小柴胡汤解外，再用柴胡加芒硝汤。"},
  {id:105, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒十三日，过经谵语者，以有热也，当以汤下之。若小便利者，大便当硬，而反下利，脉调和者，知医以丸药下之，非其治也。若自下利者，脉当微厥，今反和者，此为内实也，调胃承气汤主之。", explain:"伤寒十三日过经谵语是有热，当用汤剂攻下；若脉调和而下利，是医误用丸药，属内实，用调胃承气汤。"},
  {id:106, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病不解，热结膀胱，其人如狂，血自下，下者愈。其外不解者，尚未可攻，当先解其外。外解已，但少腹急结者，乃可攻之，宜桃核承气汤。", explain:"太阳病不解热结膀胱，病人如狂、血自下则愈；外证未解先解外，外解后少腹急结的，用桃核承气汤攻下。"},
  {id:107, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒八九日，下之，胸满烦惊，小便不利，谵语，一身尽重，不可转侧者，柴胡加龙骨牡蛎汤主之。", explain:"伤寒八九日误下后胸满烦惊、小便不利、谵语、一身尽重不能转侧的，用柴胡加龙骨牡蛎汤。"},
  {id:108, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒，腹满谵语，寸口脉浮而紧，此肝乘脾也，名曰纵，刺期门。", explain:"伤寒腹满谵语、脉浮紧，是肝乘脾，名为纵，针刺期门。"},
  {id:109, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒发热，啬啬恶寒，大渴欲饮水，其腹必满，自汗出，小便利，其病欲解，此肝乘肺也，名曰横，刺期门。", explain:"伤寒发热恶寒、大渴欲饮、腹满，是肝乘肺，名为横，刺期门。"},
  {id:110, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病二日，反躁，凡熨其背而大汗出，大热入胃，胃中水竭，躁烦必发谵语。十余日振栗自下利者，此为欲解也。故其汗从腰以下不得汗，欲小便不得，反呕，欲失溲，足下恶风，大便硬，小便当数，而反不数及不多。大便已，头卓然而痛，其人足心必热，谷气下流故也。", explain:"太阳病误用火熨大汗出，热入胃致躁烦谵语；十余日振栗自下利是欲解；大便后头突然痛、足心热是谷气下流之故。"},
  {id:111, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病中风，以火劫发汗，邪风被火热，血气流溢，失其常度。两阳相熏灼，其身发黄，阳盛则欲衄，阴虚小便难。阴阳俱虚竭，身体则枯燥，但头汗出，剂颈而还，腹满微喘，口干咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床。小便利者，其人可治。", explain:"太阳中风误用火劫发汗，邪风与火热相合致身黄、衄、小便难、枯燥、头汗出、腹满喘、口干咽烂、谵语等，小便利的尚可治。"},
  {id:112, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒脉浮，医以火迫劫之，亡阳必惊狂，卧起不安者，桂枝去芍药加蜀漆牡蛎龙骨救逆汤主之。", explain:"伤寒脉浮，误用火法发汗致亡阳惊狂、卧起不安的，用桂枝去芍药加蜀漆牡蛎龙骨救逆汤。"},
  {id:113, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"形作伤寒，其脉不弦紧而弱。弱者必渴，被火必谵语。弱者发热脉浮，解之当汗出愈。", explain:"形似伤寒而脉不弦紧反弱，脉弱必渴，误用火法必谵语；脉弱发热脉浮的，发汗即愈。"},
  {id:114, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，以火熏之，不得汗，其人必躁，到经不解，必清血，名为火邪。", explain:"太阳病用火熏不得汗，病人必躁，病久不解必便血，名为火邪。"},
  {id:115, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"脉浮热甚，而反灸之，此为实。实以虚治，因火而动，必咽燥吐血。", explain:"脉浮热甚反用灸法，是实证误用虚治，因火而动，必咽燥吐血。"},
  {id:116, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"微数之脉，慎不可灸。因火为邪，则为烦逆；追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也。欲自解者，必当先烦，烦乃有汗而解。何以知之？脉浮，故知汗出解也。", explain:"微数之脉慎不可灸；灸则火邪为害。脉浮宜汗解，误灸则邪无从出，从腰以下重而痹，名为火逆；欲自解者必先烦而后汗出解。"},
  {id:117, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"烧针令其汗，针处被寒，核起而赤者，必发奔豚。气从少腹上冲心者，灸其核上各一壮，与桂枝加桂汤，更加桂二两也。", explain:"烧针发汗后针处受寒起红核，必发奔豚，气从少腹上冲心；灸核上各一壮，并用桂枝加桂汤。"},
  {id:118, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"火逆下之，因烧针烦躁者，桂枝甘草龙骨牡蛎汤主之。", explain:"火逆误下又烧针致烦躁的，用桂枝甘草龙骨牡蛎汤。"},
  {id:119, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳伤寒者，加温针必惊也。", explain:"太阳伤寒加温针，必致惊惕。"},
  {id:120, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，当恶寒发热，今自汗出，反不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，以医吐之所致也，此为小逆。", explain:"太阳病本应恶寒发热，今反自汗、不恶寒发热、关上脉细数，是医误吐之过；属小逆。"},
  {id:121, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病吐之，但太阳病当恶寒，今反不恶寒，不欲近衣，此为吐之内烦也。", explain:"太阳病误吐后反不恶寒、不欲近衣，是吐后内烦生热。"},
  {id:122, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"病人脉数，数为热，当消谷引食，而反吐者，此以发汗，令阳气微，膈气虚，脉乃数也。数为客热，不能消谷，以胃中虚冷，故吐也。", explain:"脉数本主热应消谷善饥，反呕吐，是发汗致阳气微、膈气虚，虚寒之故。"},
  {id:123, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，过经十余日，心下温温欲吐，而胸中痛，大便反溏，腹微满，郁郁微烦。先此时自极吐下者，与调胃承气汤；若不尔者，不可与。但欲呕，胸中痛，微溏者，此非柴胡汤证，以呕故知极吐下也。", explain:"太阳病过经十余日，心下温温欲吐、胸中痛、大便溏、腹微满，若先已吐下过，用调胃承气汤；否则不可用。"},
  {id:124, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病六七日，表证仍在，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当硬满，小便自利者，下血乃愈。所以然者，以太阳随经，瘀热在里故也，抵当汤主之。", explain:"太阳病六七日表证仍在、脉微沉、发狂、少腹硬满、小便自利，是瘀热在里，用抵当汤下血则愈。"},
  {id:125, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病身黄，脉沉结，少腹硬，小便不利者，为无血也；小便自利，其人如狂者，血证谛也，抵当汤主之。", explain:"太阳病身黄、脉沉结、少腹硬，小便不利是无瘀血；小便自利、如狂是瘀血确证，用抵当汤。"},
  {id:126, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"伤寒有热，少腹满，应小便不利，今反利者，为有血也，当下之，不可余药，宜抵当丸。", explain:"伤寒有热、少腹满，小便反利是有瘀血，当攻下，用抵当丸。"},
  {id:127, chapter:"辨太阳病脉证并治（中）", category:"太阳病", text:"太阳病，小便利者，以饮水多，必心下悸；小便少者，必苦里急也。", explain:"太阳病小便通利而饮水多，必心下悸；小便少，必苦于少腹里急。"},

  // ========== 辨太阳病脉证并治（下）第 128-178 条 ==========
  {id:128, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"问曰：病有结胸，有脏结，其状何如？答曰：按之痛，寸脉浮，关脉沉，名曰结胸也。", explain:"问结胸与脏结的区别，答：按之痛、寸浮关沉的叫结胸。"},
  {id:129, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"何谓脏结？答曰：如结胸状，饮食如故，时时下利，寸脉浮，关脉小细沉紧，名曰脏结。舌上白苔滑者，难治。", explain:"脏结状如结胸，但饮食如常、时时下利、关脉小细沉紧；舌上白苔滑的难治。"},
  {id:130, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"脏结无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也。", explain:"脏结无阳热证、不往来寒热、病人反静、舌苔滑的，不可攻下。"},
  {id:131, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"病发于阳，而反下之，热入因作结胸；病发于阴，而反下之，因作痞也。所以成结胸者，以下之太早故也。结胸者，项亦强，如柔痉状，下之则和，宜大陷胸丸。", explain:"病发于阳误下，热入形成结胸；发于阴误下形成痞。结胸项强如柔痉的，宜大陷胸丸。"},
  {id:132, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"结胸证，其脉浮大者，不可下，下之则死。", explain:"结胸证脉浮大的不可攻下，攻下则死。"},
  {id:133, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"结胸证悉具，烦躁者亦死。", explain:"结胸证全部具备而又烦躁的，也是死证。"},
  {id:134, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，数则为虚。头痛发热，微盗汗出，而反恶寒者，表未解也。医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气躁烦，心中懊憹，阳气内陷，心下因硬，则为结胸，大陷胸汤主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄。", explain:"太阳病表未解而误下，阳气内陷心下硬则成结胸，用大陷胸汤；若不结胸而头汗出、身黄，是湿热发黄。"},
  {id:135, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒六七日，结胸热实，脉沉而紧，心下痛，按之石硬者，大陷胸汤主之。", explain:"伤寒六七日热实结胸，脉沉紧、心下痛、按之石硬的，用大陷胸汤。"},
  {id:136, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒十余日，热结在里，复往来寒热者，与大柴胡汤；但结胸，无大热者，此为水结在胸胁也，但头微汗出者，大陷胸汤主之。", explain:"伤寒十余日热结在里，往来寒热的用大柴胡汤；但结胸无大热、头微汗出是水结胸胁，用大陷胸汤。"},
  {id:137, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳病，重发汗而复下之，不大便五六日，舌上燥而渴，日晡所小有潮热，从心下至少腹硬满而痛不可近者，大陷胸汤主之。", explain:"太阳病重发汗又攻下，不大便五六日、舌燥渴、日晡潮热、心下至少腹硬满痛不可近的，用大陷胸汤。"},
  {id:138, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"小结胸病，正在心下，按之则痛，脉浮滑者，小陷胸汤主之。", explain:"小结胸病正中心下、按之则痛、脉浮滑的，用小陷胸汤。"},
  {id:139, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，此本有寒分也。反下之，若利止，必作结胸；未止者，四日复下之，此作协热利也。", explain:"太阳病二三日本有寒分、脉微弱，误下后若利止必作结胸，未止则作协热利。"},
  {id:140, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳病，下之，其脉促，不结胸者，此为欲解也。脉浮者，必结胸；脉紧者，必咽痛；脉弦者，必两胁拘急；脉细数者，头痛未止；脉沉紧者，必欲呕；脉沉滑者，协热利；脉浮滑者，必下血。", explain:"太阳病误下后依脉象判断病情：脉促不结胸是欲解，浮者结胸，紧者咽痛，弦者两胁拘急，细数者头痛未止，沉紧者欲呕，沉滑者协热利，浮滑者下血。"},
  {id:141, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，肉上粟起，意欲饮水，反不渴者，服文蛤散；若不差者，与五苓散。", explain:"病在阳本应发汗，反用冷水浇灌，热被劫不能去，更烦、皮肤起粟、欲饮不渴的，服文蛤散；不愈用五苓散。"},
  {id:142, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"寒实结胸，无热证者，与三物小陷胸汤，白散亦可服。", explain:"寒实结胸无热证的，用三物白散治疗。"},
  {id:143, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞硬者，当刺大椎第一间、肺俞、肝俞，慎不可发汗；发汗则谵语，脉弦。五日谵语不止，当刺期门。", explain:"太阳少阳并病，头项强痛、眩冒、心下痞硬的，针刺大椎、肺俞、肝俞，不可发汗；发汗则谵语脉弦，刺期门。"},
  {id:144, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"妇人中风，七八日续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，发作有时，小柴胡汤主之。", explain:"妇人中风七八日寒热发作有时、经水适断，是热入血室，用小柴胡汤。"},
  {id:145, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"妇人伤寒，发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室。无犯胃气及上二焦，必自愈。", explain:"妇人伤寒发热、经水适来、昼清暮谵，是热入血室；不犯胃气及上二焦，必自愈。"},
  {id:146, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，柴胡桂枝汤主之。", explain:"伤寒六七日发热微恶寒、关节烦疼、微呕、心下支结、外证未去的，用柴胡桂枝汤。"},
  {id:147, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒五六日，已发汗而复下之，胸胁满微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，柴胡桂枝干姜汤主之。", explain:"伤寒五六日汗下后胸胁满微结、小便不利、渴不呕、头汗出、往来寒热、心烦的，用柴胡桂枝干姜汤。"},
  {id:148, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便硬，脉细者，此为阳微结，必有表，复有里也。脉沉，亦在里也。汗出为阳微。假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也。脉虽沉紧，不得为少阴病。所以然者，阴不得有汗，今头汗出，故知非少阴也，可与小柴胡汤。设不了了者，得屎而解。", explain:"伤寒五六日头汗出、微恶寒、手足冷、心下满、不欲食、大便硬、脉细，是阳微结，半在里半在外，可与小柴胡汤，得大便则解。"},
  {id:149, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒五六日，呕而发热者，柴胡汤证具，而以他药下之，柴胡证仍在者，复与柴胡汤。此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解。若心下满而硬痛者，此为结胸也，大陷胸汤主之。但满而不痛者，此为痞，柴胡不中与之，宜半夏泻心汤。", explain:"伤寒五六日呕而发热，柴胡证具而误下，柴胡证仍在者仍给柴胡汤，会战汗而解；若心下满硬痛是结胸用大陷胸汤；但满不痛是痞，宜半夏泻心汤。"},
  {id:150, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳少阳并病，而反下之，成结胸，心下硬，下利不止，水浆不下，其人心烦。", explain:"太阳少阳并病误下，成结胸、心下硬、下利不止、水浆不下、心烦，病情危重。"},
  {id:151, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"脉浮而紧，而复下之，紧反入里，则作痞。按之自濡，但气痞耳。", explain:"脉浮紧而误下，紧脉入里则成痞，按之柔软，是无形气痞。"},
  {id:152, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳中风，下利呕逆，表解者，乃可攻之。其人漐漐汗出，发作有时，头痛，心下痞硬满，引胁下痛，干呕短气，汗出不恶寒者，此表解里未和也，十枣汤主之。", explain:"太阳中风下利呕逆，表已解方可攻下；漐漐汗出、发作有时、头痛、心下痞硬满、引胁下痛、干呕短气的，用十枣汤。"},
  {id:153, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳病，医发汗，遂发热恶寒，因复下之，心下痞，表里俱虚，阴阳气并竭。无阳则阴独，复加烧针，因胸烦，面色青黄，肤瞤者，难治；今色微黄，手足温者，易愈。", explain:"太阳病汗下误治致表里俱虚、心下痞，复加烧针更伤；面色青黄、肤瞤者难治，色微黄、手足温者易愈。"},
  {id:154, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"心下痞，按之濡，其脉关上浮者，大黄黄连泻心汤主之。", explain:"心下痞、按之软、关上脉浮的，用大黄黄连泻心汤。"},
  {id:155, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"心下痞，而复恶寒汗出者，附子泻心汤主之。", explain:"心下痞又怕冷汗出的，用附子泻心汤。"},
  {id:156, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"本以下之，故心下痞，与泻心汤。痞不解，其人渴而口燥烦，小便不利者，五苓散主之。", explain:"误下致心下痞，用泻心汤；痞不解而渴、口燥烦、小便不利的，用五苓散。"},
  {id:157, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒汗出解之后，胃中不和，心下痞硬，干噫食臭，胁下有水气，腹中雷鸣下利者，生姜泻心汤主之。", explain:"伤寒汗出解后胃中不和、心下痞硬、干噫食臭、腹鸣下利的，用生姜泻心汤。"},
  {id:158, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒中风，医反下之，其人下利日数十行，谷不化，腹中雷鸣，心下痞硬而满，干呕心烦不得安。医见心下痞，谓病不尽，复下之，其痞益甚。此非结热，但以胃中虚，客气上逆，故使硬也。甘草泻心汤主之。", explain:"伤寒中风误下后下利日数十行、谷不化、腹鸣、心下痞硬、干呕心烦，再误下痞更甚，是胃中虚、客气上逆，用甘草泻心汤。"},
  {id:159, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒服汤药，下利不止，心下痞硬。服泻心汤已，复以他药下之，利不止。医以理中与之，利益甚。理中者，理中焦，此利在下焦，赤石脂禹余粮汤主之。复不止者，当利其小便。", explain:"伤寒下利不止、心下痞硬，服泻心汤后又被误下利不止，用理中更甚，是利在下焦，用赤石脂禹余粮汤；再不止当利小便。"},
  {id:160, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒吐下后，发汗，虚烦，脉甚微，八九日心下痞硬，胁下痛，气上冲咽喉，眩冒，经脉动惕者，久而成痿。", explain:"伤寒吐下发汗后虚烦、脉甚微，久则心下痞硬、胁下痛、气上冲、眩冒、经脉动惕，日久成痿。"},
  {id:161, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒发汗，若吐若下，解后，心下痞硬，噫气不除者，旋覆代赭汤主之。", explain:"伤寒汗吐下后，心下痞硬、嗳气不止的，用旋覆代赭汤。"},
  {id:162, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"下后，不可更行桂枝汤，若汗出而喘，无大热者，可与麻黄杏仁甘草石膏汤。", explain:"攻下后汗出而喘、无大热，不可再用桂枝汤，用麻杏甘石汤。"},
  {id:163, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳病，外证未除而数下之，遂协热而利，利下不止，心下痞硬，表里不解者，桂枝人参汤主之。", explain:"太阳病外证未除而屡下，协热下利不止、心下痞硬、表里不解的，用桂枝人参汤。"},
  {id:164, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒大下后，复发汗，心下痞，恶寒者，表未解也。不可攻痞，当先解表，表解乃可攻痞。解表宜桂枝汤，攻痞宜大黄黄连泻心汤。", explain:"伤寒大下又发汗后心下痞、恶寒是表未解，先解表用桂枝汤，表解后再攻痞用大黄黄连泻心汤。"},
  {id:165, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒发热，汗出不解，心中痞硬，呕吐而下利者，大柴胡汤主之。", explain:"伤寒发热汗出不解、心中痞硬、呕吐下利的，用大柴胡汤。"},
  {id:166, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞硬，气上冲喉咽不得息者，此为胸有寒也，当吐之，宜瓜蒂散。", explain:"病似桂枝证但头不痛项不强、寸脉微浮、胸中痞硬、气上冲咽喉，是胸中有寒实，当用瓜蒂散催吐。"},
  {id:167, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"病胁下素有痞，连在脐旁，痛引少腹入阴筋者，此名脏结，死。", explain:"胁下素有痞块连及脐旁、痛引少腹入阴筋的，名脏结，是死证。"},
  {id:168, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒若吐若下后，七八日不解，热结在里，表里俱热，时时恶风，大渴，舌上干燥而烦，欲饮水数升者，白虎加人参汤主之。", explain:"伤寒吐下后七八日不解、热结在里、表里俱热、大渴舌燥欲饮水的，用白虎加人参汤。"},
  {id:169, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒无大热，口燥渴，心烦，背微恶寒者，白虎加人参汤主之。", explain:"伤寒无大热、口燥渴、心烦、背微恶寒的，用白虎加人参汤。"},
  {id:170, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒脉浮，发热无汗，其表不解，不可与白虎汤。渴欲饮水，无表证者，白虎加人参汤主之。", explain:"伤寒脉浮、发热无汗、表不解不可用白虎汤；渴欲饮水无表证的，用白虎加人参汤。"},
  {id:171, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳少阳并病，心下硬，颈项强而眩者，当刺大椎、肺俞、肝俞，慎勿下之。", explain:"太阳少阳并病，心下硬、颈项强、眩的，刺大椎、肺俞、肝俞，不可攻下。"},
  {id:172, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"太阳与少阳合病，自下利者，与黄芩汤；若呕者，黄芩加半夏生姜汤主之。", explain:"太阳少阳合病自下利的用黄芩汤，呕吐的加半夏生姜。"},
  {id:173, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒，胸中有热，胃中有邪气，腹中痛，欲呕吐者，黄连汤主之。", explain:"伤寒胸中有热、胃中有邪、腹中痛、欲呕吐的，用黄连汤。"},
  {id:174, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒八九日，风湿相搏，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，桂枝附子汤主之。若其人大便硬，小便自利者，去桂加白术汤主之。", explain:"伤寒八九日风湿相搏、身疼烦不能转侧、不呕不渴、脉浮虚涩的，用桂枝附子汤；大便硬、小便自利的用去桂加白术汤。"},
  {id:175, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"风湿相搏，骨节疼烦，掣痛不得屈伸，近之则痛剧，汗出短气，小便不利，恶风不欲去衣，或身微肿者，甘草附子汤主之。", explain:"风湿相搏、骨节疼烦、掣痛难屈伸、汗出短气、小便不利、恶风、身微肿的，用甘草附子汤。"},
  {id:176, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒脉浮滑，此以表有热，里有寒，白虎汤主之。", explain:"伤寒脉浮滑，是表有热，用白虎汤。"},
  {id:177, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"伤寒脉结代，心动悸，炙甘草汤主之。", explain:"伤寒脉结代、心动悸的，用炙甘草汤。"},
  {id:178, chapter:"辨太阳病脉证并治（下）", category:"太阳病", text:"脉按之来缓，时一止复来者，名曰结。又脉来动而中止，更来小数，中有还者反动，名曰结，阴也。脉来动而中止，不能自还，因而复动者，名曰代，阴也。得此脉者，必难治。", explain:"脉缓而时有停顿的称结脉，脉动中止不能自还的称代脉，得此二脉必难治。"},

  // ========== 辨阳明病脉证并治 第 179-262 条 ==========
  {id:179, chapter:"辨阳明病脉证并治", category:"阳明病", text:"问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也？答曰：太阳阳明者，脾约是也；正阳阳明者，胃家实是也；少阳阳明者，发汗利小便已，胃中燥烦实，大便难是也。", explain:"阳明病有三种：太阳阳明是脾约，正阳阳明是胃家实，少阳阳明是汗利后胃燥大便难。"},
  {id:180, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明之为病，胃家实是也。", explain:"阳明病的提纲：胃肠燥热结实。"},
  {id:181, chapter:"辨阳明病脉证并治", category:"阳明病", text:"问曰：何缘得阳明病？答曰：太阳病，若发汗、若下、若利小便，此亡津液，胃中干燥，因转属阳明。不更衣，内实，大便难者，此名阳明也。", explain:"太阳病发汗、攻下、利小便伤津液，胃中干燥而转属阳明，不大便、内实、大便难。"},
  {id:182, chapter:"辨阳明病脉证并治", category:"阳明病", text:"问曰：阳明病外证云何？答曰：身热，汗自出，不恶寒，反恶热也。", explain:"阳明病的外证：身热、自汗出、不怕冷反怕热。"},
  {id:183, chapter:"辨阳明病脉证并治", category:"阳明病", text:"问曰：病有得之一日，不发热而恶寒者，何也？答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。", explain:"阳明病初得一日不发热而恶寒，但恶寒很快自罢，随即自汗出而恶热。"},
  {id:184, chapter:"辨阳明病脉证并治", category:"阳明病", text:"问曰：恶寒何故自罢？答曰：阳明居中，主土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。", explain:"阳明居中属土，万物所归、不再传变，故初起恶寒二日自止。"},
  {id:185, chapter:"辨阳明病脉证并治", category:"阳明病", text:"本太阳初得病时，发其汗，汗先出不彻，因转属阳明也。伤寒发热无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。", explain:"太阳病发汗不彻转属阳明；伤寒发热无汗、呕不能食反濈濈汗出，是转属阳明。"},
  {id:186, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒三日，阳明脉大。", explain:"伤寒三日病及阳明，脉象洪大。"},
  {id:187, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒脉浮而缓，手足自温者，是为系在太阴。太阴者，身当发黄，若小便自利者，不能发黄。至七八日大便硬者，为阳明病也。", explain:"伤寒脉浮缓、手足自温是系在太阴；小便自利则不发黄，七八日大便硬则转阳明病。"},
  {id:188, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒转系阳明者，其人濈然微汗出也。", explain:"伤寒转属阳明，病人濈然微微汗出。"},
  {id:189, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明中风，口苦咽干，腹满微喘，发热恶寒，脉浮而紧。若下之，则腹满小便难也。", explain:"阳明中风口苦咽干、腹满微喘、发热恶寒、脉浮紧，误下则腹满、小便难。"},
  {id:190, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，若能食，名中风；不能食，名中寒。", explain:"阳明病能食的叫中风，不能食的叫中寒。"},
  {id:191, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，若中寒者，不能食，小便不利，手足濈然汗出，此欲作固瘕，必大便初硬后溏。所以然者，以胃中冷，水谷不别故也。", explain:"阳明中寒不能食、小便不利、手足濈然汗出，是欲作固瘕，大便初硬后溏，因胃中冷、水谷不别。"},
  {id:192, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，初欲食，小便反不利，大便自调，其人骨节疼，翕翕如有热状，奄然发狂，濈然汗出而解者，此水不胜谷气，与汗共并，脉紧则愈。", explain:"阳明病初欲食、小便不利、大便自调、骨节疼、如热状、忽然发狂、濈然汗出而解，是水不胜谷气，脉紧则愈。"},
  {id:193, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病欲解时，从申至戌上。", explain:"阳明病欲解的时间，在申时到戌时（下午3点到晚上9点）。"},
  {id:194, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，不能食，攻其热必哕。所以然者，胃中虚冷故也。以其人本虚，攻其热必哕。", explain:"阳明病不能食，攻其热必哕，因胃中虚冷、其人本虚。"},
  {id:195, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，脉迟，食难用饱，饱则微烦头眩，必小便难，此欲作谷瘅。虽下之，腹满如故。所以然者，脉迟故也。", explain:"阳明病脉迟、食难用饱、饱则微烦头眩、小便难，是欲作谷瘅，脉迟不可攻下。"},
  {id:196, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，法多汗，反无汗，其身如虫行皮中状者，此以久虚故也。", explain:"阳明病本应多汗，反无汗、身如虫行皮中，是久虚之故。"},
  {id:197, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳不呕，手足不厥者，头不痛。", explain:"阳明病反无汗而小便利，二三日呕咳、手足厥的必苦头痛；不咳不呕不厥的头不痛。"},
  {id:198, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，但头眩，不恶寒，故能食而咳，其人咽必痛；若不咳者，咽不痛。", explain:"阳明病但头眩、不恶寒、能食而咳的，咽必痛；不咳则咽不痛。"},
  {id:199, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，无汗，小便不利，心中懊憹者，身必发黄。", explain:"阳明病无汗、小便不利、心中懊憹的，身必发黄。"},
  {id:200, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，被火，额上微汗出，而小便不利者，必发黄。", explain:"阳明病误用火法，额上微汗出而小便不利的，必发黄。"},
  {id:201, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，脉浮而紧者，必潮热，发作有时；但浮者，必盗汗出。", explain:"阳明病脉浮紧的必潮热发作有时，脉只浮的必盗汗出。"},
  {id:202, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，口燥但欲漱水，不欲咽者，此必衄。", explain:"阳明病口燥只想漱水不想咽下的，必鼻衄。"},
  {id:203, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，本自汗出，医更重发汗，病已差，尚微烦不了了者，此必大便硬故也。以亡津液，胃中干燥，故令大便硬。当问其小便日几行，若本小便日三四行，今日再行，故知大便不久出。今为小便数少，以津液当还入胃中，故知不久必大便也。", explain:"阳明病本自汗出又被重发汗，微烦不解是大便硬、津液伤；问小便次数减少，是津液还入胃中，不久必大便。"},
  {id:204, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒呕多，虽有阳明证，不可攻之。", explain:"伤寒呕吐多的，虽有阳明证也不可攻下。"},
  {id:205, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，心下硬满者，不可攻之。攻之利遂不止者死，利止者愈。", explain:"阳明病心下硬满不可攻下，攻后下利不止者死，利止者愈。"},
  {id:206, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，面合色赤，不可攻之，必发热色黄，小便不利也。", explain:"阳明病面赤不可攻下，攻下必发热、色黄、小便不利。"},
  {id:207, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，不吐不下，心烦者，可与调胃承气汤。", explain:"阳明病不吐不下而心烦的，可用调胃承气汤。"},
  {id:208, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，脉迟，虽汗出不恶寒者，其身必重，短气，腹满而喘，有潮热者，此外欲解，可攻里也。手足濈然汗出者，此大便已硬也，大承气汤主之。若汗多，微发热恶寒者，外未解也，其热不潮，未可与承气汤。若腹大满不通者，可与小承气汤微和胃气，勿令至大泄下。", explain:"阳明病脉迟、汗出不恶寒、身重短气、腹满喘、有潮热，是外欲解可攻里；手足濈然汗出是大便硬，用大承气汤；外未解不可用；腹大满不通可用小承气汤。"},
  {id:209, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，潮热，大便微硬者，可与大承气汤；不硬者，不可与之。若不大便六七日，恐有燥屎，欲知之法，少与小承气汤，汤入腹中，转失气者，此有燥屎也，乃可攻之。若不转失气者，此但初头硬，后必溏，不可攻之，攻之必胀满不能食也。欲饮水者，与水则哕。其后发热者，必大便复硬而少也，以小承气汤和之。不转失气者，慎不可攻也。", explain:"阳明病潮热、大便微硬可用大承气汤，不硬不可用；判断燥屎可先给小承气汤，转失气则有燥屎可攻，不转失气则不可攻。"},
  {id:210, chapter:"辨阳明病脉证并治", category:"阳明病", text:"夫实则谵语，虚则郑声。郑声者，重语也。直视谵语，喘满者死，下利者亦死。", explain:"实证则谵语，虚证则郑声（语言重复）；直视谵语、喘满者死，下利者亦死。"},
  {id:211, chapter:"辨阳明病脉证并治", category:"阳明病", text:"发汗多，若重发汗者，亡其阳，谵语，脉短者死；脉自和者不死。", explain:"发汗过多再发汗，亡阳谵语、脉短者死，脉自和者不死。"},
  {id:212, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒若吐若下后不解，不大便五六日，上至十余日，日晡所发潮热，不恶寒，独语如见鬼状。若剧者，发则不识人，循衣摸床，惕而不安，微喘直视，脉弦者生，涩者死。微者，但发热谵语者，大承气汤主之。若一服利，则止后服。", explain:"伤寒吐下后不解、不大便、日晡潮热、独语如见鬼状，剧则不识人、循衣摸床、微喘直视；脉弦者生、涩者死；轻者用大承气汤，一服利则停药。"},
  {id:213, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，其人多汗，以津液外出，胃中燥，大便必硬，硬则谵语，小承气汤主之。若一服谵语止者，更莫复服。", explain:"阳明病多汗、津液外出、胃燥大便硬而谵语的，用小承气汤，谵语止则停服。"},
  {id:214, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，谵语发潮热，脉滑而疾者，小承气汤主之。因与承气汤一升，腹中转气者，更服一升；若不转气者，勿更与之。明日又不大便，脉反微涩者，里虚也，为难治，不可更与承气汤也。", explain:"阳明病谵语潮热、脉滑疾的用小承气汤；腹中转气者再服，不转气者停；脉反微涩是里虚难治，不可再用承气汤。"},
  {id:215, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，谵语有潮热，反不能食者，胃中必有燥屎五六枚也。若能食者，但硬耳，宜大承气汤下之。", explain:"阳明病谵语潮热、反不能食，胃中必有燥屎；能食者仅大便硬，宜大承气汤下之。"},
  {id:216, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，下血谵语者，此为热入血室。但头汗出者，刺期门，随其实而泻之，濈然汗出则愈。", explain:"阳明病下血谵语是热入血室，头汗出的刺期门，泻其实则濈然汗出而愈。"},
  {id:217, chapter:"辨阳明病脉证并治", category:"阳明病", text:"汗出谵语者，以有燥屎在胃中，此为风也。须下者，过经乃可下之。下之若早，语言必乱，以表虚里实故也。下之愈，宜大承气汤。", explain:"汗出谵语是胃中有燥屎兼表邪，须过经后方可攻下，宜大承气汤；下之过早会语言错乱。"},
  {id:218, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒四五日，脉沉而喘满，沉为在里，而反发其汗，津液越出，大便为难，表虚里实，久则谵语。", explain:"伤寒四五日脉沉喘满，病在里反发汗，津液外越致大便难、表虚里实，久则谵语。"},
  {id:219, chapter:"辨阳明病脉证并治", category:"阳明病", text:"三阳合病，腹满身重，难以转侧，口不仁，面垢，谵语，遗尿。发汗则谵语，下之则额上生汗，手足逆冷。若自汗出者，白虎汤主之。", explain:"三阳合病腹满身重、口不仁、面垢、谵语、遗尿，自汗出的用白虎汤；发汗下之皆误。"},
  {id:220, chapter:"辨阳明病脉证并治", category:"阳明病", text:"二阳并病，太阳证罢，但发潮热，手足漐漐汗出，大便难而谵语者，下之则愈，宜大承气汤。", explain:"太阳阳明并病，太阳证已罢、发潮热、手足汗出、大便难谵语的，下之则愈，宜大承气汤。"},
  {id:221, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，脉浮而紧，咽燥口苦，腹满而喘，发热汗出，不恶寒，反恶热，身重。若发汗则躁，心愦愦反谵语；若加温针，必怵惕烦躁不得眠；若下之，则胃中空虚，客气动膈，心中懊憹，舌上苔者，栀子豉汤主之。", explain:"阳明病脉浮紧、咽燥口苦、腹满喘、发热汗出不恶寒反恶热、身重，误汗误温针皆变证；误下后心中懊憹、舌有苔的用栀子豉汤。"},
  {id:222, chapter:"辨阳明病脉证并治", category:"阳明病", text:"若渴欲饮水，口干舌燥者，白虎加人参汤主之。", explain:"渴欲饮水、口干舌燥的，用白虎加人参汤。"},
  {id:223, chapter:"辨阳明病脉证并治", category:"阳明病", text:"若脉浮发热，渴欲饮水，小便不利者，猪苓汤主之。", explain:"脉浮发热、渴欲饮水、小便不利的，用猪苓汤。"},
  {id:224, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，汗出多而渴者，不可与猪苓汤，以汗多胃中燥，猪苓汤复利其小便故也。", explain:"阳明病汗多而渴不可用猪苓汤，因汗多胃燥，猪苓汤再利小便更伤津。"},
  {id:225, chapter:"辨阳明病脉证并治", category:"阳明病", text:"脉浮而迟，表热里寒，下利清谷者，四逆汤主之。", explain:"脉浮迟、表热里寒、下利清谷的，用四逆汤。"},
  {id:226, chapter:"辨阳明病脉证并治", category:"阳明病", text:"若胃中虚冷，不能食者，饮水则哕。", explain:"胃中虚冷、不能食的，饮水则哕。"},
  {id:227, chapter:"辨阳明病脉证并治", category:"阳明病", text:"脉浮发热，口干鼻燥，能食者则衄。", explain:"脉浮发热、口干鼻燥、能食的，则鼻衄。"},
  {id:228, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，下之，其外有热，手足温，不结胸，心中懊憹，饥不能食，但头汗出者，栀子豉汤主之。", explain:"阳明病攻下后外有热、手足温、心中懊憹、饥不能食、但头汗出的，用栀子豉汤。"},
  {id:229, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，发潮热，大便溏，小便自可，胸胁满不去者，与小柴胡汤。", explain:"阳明病发潮热、大便溏、小便自可、胸胁满不去的，与小柴胡汤。"},
  {id:230, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，胁下硬满，不大便而呕，舌上白苔者，可与小柴胡汤。上焦得通，津液得下，胃气因和，身濈然汗出而解。", explain:"阳明病胁下硬满、不大便而呕、舌上白苔的，可与小柴胡汤，使上焦通、津液下、胃气和而汗出解。"},
  {id:231, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明中风，脉弦浮大而短气，腹都满，胁下及心痛，久按之气不通，鼻干不得汗，嗜卧，一身及目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之小差，外不解。病过十日，脉续浮者，与小柴胡汤。", explain:"阳明中风脉弦浮大、短气、腹满、胁下及心痛、鼻干无汗、嗜卧、身目俱黄、小便难、潮热、时时哕、耳前后肿，刺之小差；病过十日脉仍浮的与小柴胡汤。"},
  {id:232, chapter:"辨阳明病脉证并治", category:"阳明病", text:"脉但浮，无余证者，与麻黄汤。若不尿，腹满加哕者，不治。", explain:"脉只浮而无其他证的，与麻黄汤；若小便不通、腹满加哕，则不治。"},
  {id:233, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，自汗出，若发汗，小便自利者，此为津液内竭，虽硬不可攻之。当须自欲大便，宜蜜煎导而通之。若土瓜根及大猪胆汁，皆可为导。", explain:"阳明病自汗、发汗后小便自利，是津液内竭，虽大便硬不可攻，应用蜜煎导法、土瓜根或猪胆汁导便。"},
  {id:234, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜桂枝汤。", explain:"阳明病脉迟、汗多、微恶寒，是表未解，可发汗，宜桂枝汤。"},
  {id:235, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，脉浮，无汗而喘者，发汗则愈，宜麻黄汤。", explain:"阳明病脉浮、无汗而喘的，发汗则愈，宜麻黄汤。"},
  {id:236, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，发热汗出者，此为热越，不能发黄也。但头汗出，身无汗，剂颈而还，小便不利，渴引水浆者，此为瘀热在里，身必发黄，茵陈蒿汤主之。", explain:"阳明病发热汗出则热越不发黄；但头汗出、身无汗、小便不利、渴饮水的，是瘀热在里，身必发黄，用茵陈蒿汤。"},
  {id:237, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明证，其人喜忘者，必有蓄血。所以然者，本有久瘀血，故令喜忘。屎虽硬，大便反易，其色必黑者，宜抵当汤下之。", explain:"阳明证喜忘是必有蓄血，因久有瘀血；大便虽硬反易、色黑的，用抵当汤下之。"},
  {id:238, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，下之，心中懊憹而烦，胃中有燥屎者，可攻。腹微满，初头硬，后必溏，不可攻之。若有燥屎者，宜大承气汤。", explain:"阳明病攻下后心中懊憹而烦、胃中有燥屎的可攻，宜大承气汤；腹微满、初硬后溏则不可攻。"},
  {id:239, chapter:"辨阳明病脉证并治", category:"阳明病", text:"病人不大便五六日，绕脐痛，烦躁，发作有时者，此有燥屎，故使不大便也。", explain:"病人不大便五六日、绕脐痛、烦躁发作有时，是有燥屎。"},
  {id:240, chapter:"辨阳明病脉证并治", category:"阳明病", text:"病人烦热，汗出则解，又如疟状，日晡所发热者，属阳明也。脉实者，宜下之；脉浮虚者，宜发汗。下之与大承气汤，发汗宜桂枝汤。", explain:"病人烦热、汗出则解、又如疟状、日晡发热属阳明；脉实的宜下用大承气汤，脉浮虚的宜汗用桂枝汤。"},
  {id:241, chapter:"辨阳明病脉证并治", category:"阳明病", text:"大下后，六七日不大便，烦不解，腹满痛者，此有燥屎也。所以然者，本有宿食故也，宜大承气汤。", explain:"大下后六七日不大便、烦不解、腹满痛，是有燥屎、本有宿食，宜大承气汤。"},
  {id:242, chapter:"辨阳明病脉证并治", category:"阳明病", text:"病人小便不利，大便乍难乍易，时有微热，喘冒不能卧者，有燥屎也，宜大承气汤。", explain:"病人小便不利、大便乍难乍易、时有微热、喘冒不能卧的，是有燥屎，宜大承气汤。"},
  {id:243, chapter:"辨阳明病脉证并治", category:"阳明病", text:"食谷欲呕，属阳明也，吴茱萸汤主之。得汤反剧者，属上焦也。", explain:"食谷欲呕属阳明中寒，用吴茱萸汤；服后反加剧的属上焦。"},
  {id:244, chapter:"辨阳明病脉证并治", category:"阳明病", text:"太阳病，寸缓关浮尺弱，其人发热汗出，复恶寒，不呕，但心下痞者，此以医下之也。如其不下者，病人不恶寒而渴者，此转属阳明也。小便数者，大便必硬，不更衣十日，无所苦也。渴欲饮水，少少与之，但以法救之。渴者，宜五苓散。", explain:"太阳病脉寸缓关浮尺弱、发热汗出恶寒、不呕、心下痞是误下；不恶寒而渴是转属阳明；小便数则大便硬；渴者宜五苓散。"},
  {id:245, chapter:"辨阳明病脉证并治", category:"阳明病", text:"脉阳微而汗出少者，为自和也；汗出多者，为太过。阳脉实，因发其汗，出多者，亦为太过。太过者，为阳绝于里，亡津液，大便因硬也。", explain:"汗出少是自和，汗出多为太过，太过则阳绝于里、亡津液、大便硬。"},
  {id:246, chapter:"辨阳明病脉证并治", category:"阳明病", text:"脉浮而芤，浮为阳，芤为阴，浮芤相搏，胃气生热，其阳则绝。", explain:"脉浮而芤，浮主阳、芤主阴血虚，浮芤相搏则胃生热、津液亡。"},
  {id:247, chapter:"辨阳明病脉证并治", category:"阳明病", text:"趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相搏，大便则硬，其脾为约，麻子仁丸主之。", explain:"趺阳脉浮涩，胃气强而小便数，则大便硬，是脾约，用麻子仁丸。"},
  {id:248, chapter:"辨阳明病脉证并治", category:"阳明病", text:"太阳病三日，发汗不解，蒸蒸发热者，属胃也，调胃承气汤主之。", explain:"太阳病三日发汗不解、蒸蒸发热的，属胃实，用调胃承气汤。"},
  {id:249, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒吐后，腹胀满者，与调胃承气汤。", explain:"伤寒吐后腹胀满的，与调胃承气汤。"},
  {id:250, chapter:"辨阳明病脉证并治", category:"阳明病", text:"太阳病，若吐若下若发汗后，微烦，小便数，大便因硬者，与小承气汤和之愈。", explain:"太阳病吐下发汗后微烦、小便数、大便硬的，用小承气汤和之即愈。"},
  {id:251, chapter:"辨阳明病脉证并治", category:"阳明病", text:"得病二三日，脉弱，无太阳柴胡证，烦躁，心下硬。至四五日，虽能食，以小承气汤少少与，微和之，令小安。至六日，与承气汤一升。若不大便六七日，小便少者，虽不受食，但初头硬，后必溏，未定成硬，攻之必溏。须小便利，屎定硬，乃可攻之，宜大承气汤。", explain:"得病二三日脉弱、无太阳柴胡证、烦躁、心下硬，先用小承气汤少少和之；小便少者不可攻，须小便利、屎定硬方可用大承气汤。"},
  {id:252, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜大承气汤。", explain:"伤寒六七日目视不明、睛不和、大便难、身微热，是里实，急下之，宜大承气汤。"},
  {id:253, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明病，发热汗多者，急下之，宜大承气汤。", explain:"阳明病发热汗多的，急下之，宜大承气汤。"},
  {id:254, chapter:"辨阳明病脉证并治", category:"阳明病", text:"发汗不解，腹满痛者，急下之，宜大承气汤。", explain:"发汗不解、腹满痛的，急下之，宜大承气汤。"},
  {id:255, chapter:"辨阳明病脉证并治", category:"阳明病", text:"腹满不减，减不足言，当下之，宜大承气汤。", explain:"腹满不减、稍减也不明显的，当下之，宜大承气汤。"},
  {id:256, chapter:"辨阳明病脉证并治", category:"阳明病", text:"阳明少阳合病，必下利。其脉不负者，为顺也；负者，失也，互相克贼，名为负也。脉滑而数者，有宿食也，当下之，宜大承气汤。", explain:"阳明少阳合病必下利，脉不相克为顺，相克为负；脉滑数是有宿食，当下，宜大承气汤。"},
  {id:257, chapter:"辨阳明病脉证并治", category:"阳明病", text:"病人无表里证，发热七八日，虽脉浮数者，可下之。假令已下，脉数不解，合热则消谷喜饥，至六七日不大便者，有瘀血，宜抵当汤。", explain:"病人无表里证、发热七八日、脉浮数可下；下后脉数不解、消谷善饥、六七日不大便是有瘀血，宜抵当汤。"},
  {id:258, chapter:"辨阳明病脉证并治", category:"阳明病", text:"若脉数不解，而下不止，必协热便脓血也。", explain:"若脉数不解而下利不止，必协热便脓血。"},
  {id:259, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒发汗已，身目为黄，所以然者，以寒湿在里不解故也。以为不可下也，于寒湿中求之。", explain:"伤寒发汗后身目发黄，是寒湿在里不解，不可攻下，当从寒湿论治。"},
  {id:260, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒七八日，身黄如橘子色，小便不利，腹微满者，茵陈蒿汤主之。", explain:"伤寒七八日身黄如橘色、小便不利、腹微满的，用茵陈蒿汤。"},
  {id:261, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒身黄发热，栀子柏皮汤主之。", explain:"伤寒身黄发热的，用栀子柏皮汤。"},
  {id:262, chapter:"辨阳明病脉证并治", category:"阳明病", text:"伤寒瘀热在里，身必黄，麻黄连轺赤小豆汤主之。", explain:"伤寒瘀热在里、身必发黄的，用麻黄连轺赤小豆汤。"},

  // ========== 辨少阳病脉证并治 第 263-272 条 ==========
  {id:263, chapter:"辨少阳病脉证并治", category:"少阳病", text:"少阳之为病，口苦，咽干，目眩也。", explain:"少阳病的提纲：口苦、咽干、目眩。"},
  {id:264, chapter:"辨少阳病脉证并治", category:"少阳病", text:"少阳中风，两耳无所闻，目赤，胸中满而烦者，不可吐下，吐下则悸而惊。", explain:"少阳中风耳聋、目赤、胸中满而烦，不可吐下，吐下则心悸而惊。"},
  {id:265, chapter:"辨少阳病脉证并治", category:"少阳病", text:"伤寒，脉弦细，头痛发热者，属少阳。少阳不可发汗，发汗则谵语。此属胃，胃和则愈，胃不和，烦而悸。", explain:"伤寒脉弦细、头痛发热属少阳，不可发汗，发汗则谵语；胃和则愈。"},
  {id:266, chapter:"辨少阳病脉证并治", category:"少阳病", text:"本太阳病不解，转入少阳者，胁下硬满，干呕不能食，往来寒热，尚未吐下，脉沉紧者，与小柴胡汤。", explain:"太阳病不解转入少阳，胁下硬满、干呕不能食、往来寒热、脉沉紧的，与小柴胡汤。"},
  {id:267, chapter:"辨少阳病脉证并治", category:"少阳病", text:"若已吐下、发汗、温针，谵语，柴胡汤证罢，此为坏病。知犯何逆，以法治之。", explain:"若已吐下发汗温针致谵语、柴胡证已罢，是坏病，当辨误治随证治之。"},
  {id:268, chapter:"辨少阳病脉证并治", category:"少阳病", text:"三阳合病，脉浮大，上关上，但欲眠睡，目合则汗。", explain:"三阳合病，脉浮大、关上明显、但欲眠睡、闭目则汗出。"},
  {id:269, chapter:"辨少阳病脉证并治", category:"少阳病", text:"伤寒六七日，无大热，其人躁烦者，此为阳去入阴故也。", explain:"伤寒六七日无大热而躁烦，是病由阳入阴。"},
  {id:270, chapter:"辨少阳病脉证并治", category:"少阳病", text:"伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。", explain:"伤寒三日三阳经尽、三阴当受邪，但能食不呕，说明三阴不受邪。"},
  {id:271, chapter:"辨少阳病脉证并治", category:"少阳病", text:"伤寒三日，少阳脉小者，欲已也。", explain:"伤寒三日少阳脉小，是病将愈。"},
  {id:272, chapter:"辨少阳病脉证并治", category:"少阳病", text:"少阳病欲解时，从寅至辰上。", explain:"少阳病欲解的时间，在寅时到辰时（凌晨3点到上午9点）。"},

  // ========== 辨太阴病脉证并治 第 273-280 条 ==========
  {id:273, chapter:"辨太阴病脉证并治", category:"太阴病", text:"太阴之为病，腹满而吐，食不下，自利益甚，时腹自痛。若下之，必胸下结硬。", explain:"太阴病的提纲：腹满而吐、食不下、下利更甚、时腹自痛；误下则胸下结硬。"},
  {id:274, chapter:"辨太阴病脉证并治", category:"太阴病", text:"太阴中风，四肢烦疼，阳微阴涩而长者，为欲愈。", explain:"太阴中风四肢烦疼、脉阳微阴涩而长的，是欲愈。"},
  {id:275, chapter:"辨太阴病脉证并治", category:"太阴病", text:"太阴病，欲解时，从亥至丑上。", explain:"太阴病欲解的时间，在亥时到丑时（晚上9点到凌晨3点）。"},
  {id:276, chapter:"辨太阴病脉证并治", category:"太阴病", text:"太阴病，脉浮者，可发汗，宜桂枝汤。", explain:"太阴病脉浮的，可发汗，宜桂枝汤。"},
  {id:277, chapter:"辨太阴病脉证并治", category:"太阴病", text:"自利不渴者，属太阴，以其脏有寒故也，当温之，宜服四逆辈。", explain:"自下利而不口渴的属太阴，因脏有寒，当温里，宜服四逆汤之类。"},
  {id:278, chapter:"辨太阴病脉证并治", category:"太阴病", text:"伤寒脉浮而缓，手足自温者，系在太阴。太阴当发身黄，若小便自利者，不能发黄。至七八日，虽暴烦下利日十余行，必自止，以脾家实，腐秽当去故也。", explain:"伤寒脉浮缓、手足自温系在太阴；太阴当发黄，小便自利则不黄；七八日暴烦下利日十余行，是脾家实、腐秽当去，必自止。"},
  {id:279, chapter:"辨太阴病脉证并治", category:"太阴病", text:"本太阳病，医反下之，因尔腹满时痛者，属太阴也，桂枝加芍药汤主之；大实痛者，桂枝加大黄汤主之。", explain:"太阳病误下致腹满时痛属太阴，用桂枝加芍药汤；大实痛的用桂枝加大黄汤。"},
  {id:280, chapter:"辨太阴病脉证并治", category:"太阴病", text:"太阴为病，脉弱，其人续自便利，设当行大黄、芍药者，宜减之，以其人胃气弱，易动故也。", explain:"太阴病脉弱、大便自利的，用大黄、芍药当减量，因胃气弱易受扰动。"},

  // ========== 辨少阴病脉证并治 第 281-325 条 ==========
  {id:281, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴之为病，脉微细，但欲寐也。", explain:"少阴病的提纲：脉微细、只想睡觉。"},
  {id:282, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，欲吐不吐，心烦，但欲寐，五六日自利而渴者，属少阴也，虚故引水自救。若小便色白者，少阴病形悉具。小便白者，以下焦虚有寒，不能制水，故令色白也。", explain:"少阴病欲吐不吐、心烦、但欲寐、五六日自利而渴是虚故引水自救；小便色白是下焦虚寒不能制水。"},
  {id:283, chapter:"辨少阴病脉证并治", category:"少阴病", text:"病人脉阴阳俱紧，反汗出者，亡阳也，此属少阴，法当咽痛而复吐利。", explain:"病人寸关尺脉俱紧反汗出，是亡阳、属少阴，当咽痛而复吐利。"},
  {id:284, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，咳而下利谵语者，被火气劫故也，小便必难，以强责少阴汗也。", explain:"少阴病咳、下利、谵语，是被火气劫迫，小便必难，因强发少阴汗。"},
  {id:285, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，脉细沉数，病为在里，不可发汗。", explain:"少阴病脉细沉数，病在里，不可发汗。"},
  {id:286, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，脉微，不可发汗，亡阳故也。阳已虚，尺脉弱涩者，复不可下之。", explain:"少阴病脉微不可发汗，因亡阳；阳已虚、尺脉弱涩，也不可攻下。"},
  {id:287, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，脉紧，至七八日，自下利，脉暴微，手足反温，脉紧反去者，为欲解也，虽烦下利，必自愈。", explain:"少阴病脉紧、七八日自下利、脉暴微、手足反温、脉紧反去，是欲解，虽烦下利必自愈。"},
  {id:288, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利，若利自止，恶寒而踡卧，手足温者，可治。", explain:"少阴病下利自止、恶寒踡卧、手足温的，可治。"},
  {id:289, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，恶寒而踡，时自烦，欲去衣被者，可治。", explain:"少阴病恶寒踡卧、时自烦、想去衣被的，可治。"},
  {id:290, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴中风，脉阳微阴浮者，为欲愈。", explain:"少阴中风，脉阳微阴浮的，是欲愈。"},
  {id:291, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，欲解时，从子至寅上。", explain:"少阴病欲解的时间，在子时到寅时（晚上11点到凌晨5点）。"},
  {id:292, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，吐利，手足不逆冷，反发热者，不死。脉不至者，灸少阴七壮。", explain:"少阴病吐利、手足不逆冷、反发热的，不死；脉不至的灸少阴七壮。"},
  {id:293, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病八九日，一身手足尽热者，以热在膀胱，必便血也。", explain:"少阴病八九日一身手足尽热，是热在膀胱，必便血。"},
  {id:294, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，但厥无汗，而强发之，必动其血，未知从何道出，或从口鼻，或从目出者，是名下厥上竭，为难治。", explain:"少阴病但厥无汗而强发汗，必动血，或从口鼻或从目出，名下厥上竭，难治。"},
  {id:295, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，恶寒身踡而利，手足逆冷者，不治。", explain:"少阴病恶寒身踡下利、手足逆冷的，不治。"},
  {id:296, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，吐利躁烦，四逆者死。", explain:"少阴病吐利躁烦、四肢厥逆的，死证。"},
  {id:297, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利止而头眩，时时自冒者死。", explain:"少阴病下利止而头眩、时时自冒的，死证。"},
  {id:298, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，四逆，恶寒而身踡，脉不至，不烦而躁者死。", explain:"少阴病四逆、恶寒身踡、脉不至、不烦而躁的，死证。"},
  {id:299, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，六七日，息高者死。", explain:"少阴病六七日呼吸浅表而高的，死证。"},
  {id:300, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，脉微细沉，但欲卧，汗出不烦，自欲吐，至五六日自利，复烦躁不得卧寐者死。", explain:"少阴病脉微细沉、但欲卧、汗出不烦、自欲吐、五六日自利，复烦躁不得卧的，死证。"},
  {id:301, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，始得之，反发热，脉沉者，麻黄细辛附子汤主之。", explain:"少阴病初起反发热、脉沉的，用麻黄细辛附子汤。"},
  {id:302, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，得之二三日，麻黄附子甘草汤微发汗。以二三日无证，故微发汗也。", explain:"少阴病二三日，用麻黄附子甘草汤微发汗。"},
  {id:303, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，得之二三日以上，心中烦，不得卧，黄连阿胶汤主之。", explain:"少阴病二三日以上、心中烦、不得卧的，用黄连阿胶汤。"},
  {id:304, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，得之一二日，口中和，其背恶寒者，当灸之，附子汤主之。", explain:"少阴病一二日、口中和、背恶寒的，当灸之并用附子汤。"},
  {id:305, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，身体痛，手足寒，骨节痛，脉沉者，附子汤主之。", explain:"少阴病身体痛、手足寒、骨节痛、脉沉的，用附子汤。"},
  {id:306, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利便脓血者，桃花汤主之。", explain:"少阴病下利便脓血的，用桃花汤。"},
  {id:307, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者，桃花汤主之。", explain:"少阴病腹痛、小便不利、下利不止、便脓血的，用桃花汤。"},
  {id:308, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利便脓血者，可刺。", explain:"少阴病下利便脓血的，可以针刺。"},
  {id:309, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，吐利，手足逆冷，烦躁欲死者，吴茱萸汤主之。", explain:"少阴病吐利、手足逆冷、烦躁欲死的，用吴茱萸汤。"},
  {id:310, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利，咽痛，胸满，心烦，猪肤汤主之。", explain:"少阴病下利、咽痛、胸满、心烦的，用猪肤汤。"},
  {id:311, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，二三日，咽痛者，可与甘草汤；不差者，与桔梗汤。", explain:"少阴病二三日咽痛，可用甘草汤，不愈用桔梗汤。"},
  {id:312, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，咽中伤，生疮，不能语言，声不出者，苦酒汤主之。", explain:"少阴病咽中伤、生疮、不能言语、声不出的，用苦酒汤。"},
  {id:313, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，咽中痛，半夏散及汤主之。", explain:"少阴病咽中痛的，用半夏散及汤。"},
  {id:314, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利，白通汤主之。", explain:"少阴病下利的，用白通汤。"},
  {id:315, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利脉微者，与白通汤。利不止，厥逆无脉，干呕烦者，白通加猪胆汁汤主之。服汤脉暴出者死，微续者生。", explain:"少阴病下利脉微用白通汤；利不止、厥逆无脉、干呕烦的用白通加猪胆汁汤；服后脉暴出者死、微续者生。"},
  {id:316, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气。其人或咳，或小便利，或下利，或呕者，真武汤主之。", explain:"少阴病腹痛、小便不利、四肢沉重疼痛、自下利，是有水气，用真武汤。"},
  {id:317, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止脉不出者，通脉四逆汤主之。", explain:"少阴病下利清谷、里寒外热、手足厥逆、脉微欲绝、面赤的，用通脉四逆汤。"},
  {id:318, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，四逆散主之。", explain:"少阴病四逆，或咳、或悸、或小便不利、或腹中痛、或泄利下重的，用四逆散。"},
  {id:319, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利六七日，咳而呕渴，心烦不得眠者，猪苓汤主之。", explain:"少阴病下利六七日、咳而呕渴、心烦不得眠的，用猪苓汤。"},
  {id:320, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，得之二三日，口燥咽干者，急下之，宜大承气汤。", explain:"少阴病二三日口燥咽干的，急下之，宜大承气汤。"},
  {id:321, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，自利清水，色纯青，心下必痛，口干燥者，急下之，宜大承气汤。", explain:"少阴病自利清水、色纯青、心下痛、口干燥的，急下之，宜大承气汤。"},
  {id:322, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，六七日，腹胀不大便者，急下之，宜大承气汤。", explain:"少阴病六七日腹胀、不大便的，急下之，宜大承气汤。"},
  {id:323, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，脉沉者，急温之，宜四逆汤。", explain:"少阴病脉沉的，急温之，宜四逆汤。"},
  {id:324, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，饮食入口则吐，心中温温欲吐，复不能吐。始得之，手足寒，脉弦迟者，此胸中实，不可下也，当吐之。若膈上有寒饮，干呕者，不可吐也，当温之，宜四逆汤。", explain:"少阴病饮食入口则吐、心中欲吐不能吐，手足寒、脉弦迟是胸中实，当吐；膈上有寒饮干呕的不可吐，当温，宜四逆汤。"},
  {id:325, chapter:"辨少阴病脉证并治", category:"少阴病", text:"少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。", explain:"少阴病下利、脉微涩、呕而汗出、屡欲大便而量少的，当温其上，灸之。"},

  // ========== 辨厥阴病脉证并治 第 326-381 条 ==========
  {id:326, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"厥阴之为病，消渴，气上撞心，心中疼热，饥而不欲食，食则吐蛔，下之利不止。", explain:"厥阴病的提纲：消渴、气上撞心、心中疼热、饥而不欲食、食则吐蛔、下之利不止。"},
  {id:327, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"厥阴中风，脉微浮为欲愈，不浮为未愈。", explain:"厥阴中风，脉微浮的是欲愈，不浮的是未愈。"},
  {id:328, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"厥阴病，欲解时，从丑至卯上。", explain:"厥阴病欲解的时间，在丑时到卯时（凌晨1点到7点）。"},
  {id:329, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"厥阴病，渴欲饮水者，少少与之愈。", explain:"厥阴病渴欲饮水的，少量给水即愈。"},
  {id:330, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"诸四逆厥者，不可下之，虚家亦然。", explain:"各种四肢厥逆的，不可攻下，虚证也同样。"},
  {id:331, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒先厥，后发热而利者，必自止，见厥复利。", explain:"伤寒先厥后发热而下利，必自止；再厥则又下利。"},
  {id:332, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒始发热六日，厥反九日而利。凡厥利者，当不能食，今反能食者，恐为除中。食以索饼，不发热者，知胃气尚在，必愈。恐暴热来出而复去也。后日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，与厥相应，故期之旦日夜半愈。后三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。", explain:"伤寒先发热六日、厥九日而下利，厥利当不能食，反能食恐是除中；食索饼不发热是胃气尚在必愈；若热气有余必发痈脓。"},
  {id:333, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒脉迟六七日，而反与黄芩汤彻其热。脉迟为寒，今与黄芩汤复除其热，腹中应冷，当不能食，今反能食，此名除中，必死。", explain:"伤寒脉迟六七日反用黄芩汤清其热，脉迟本寒，腹中应冷不能食，反能食是除中，必死。"},
  {id:334, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒先厥后发热，下利必自止，而反汗出，咽中痛者，其喉为痹。发热无汗，而利必自止；若不止，必便脓血。便脓血者，其喉不痹。", explain:"伤寒先厥后发热，下利当自止；反汗出咽痛是喉痹；发热无汗而下利不止的必便脓血，便脓血则喉不痹。"},
  {id:335, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒一二日至四五日厥者，必发热，前热者后必厥，厥深者热亦深，厥微者热亦微。厥应下之，而反发汗者，必口伤烂赤。", explain:"伤寒先热后厥，厥深热亦深、厥微热亦微；厥当下之，反发汗则口伤烂赤。"},
  {id:336, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈。厥终不过五日，以热五日，故知自愈。", explain:"伤寒厥五日、热亦五日，第六日不再厥则自愈，因厥与热相等。"},
  {id:337, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷者是也。", explain:"凡厥是阴阳气不相顺接，表现为手足逆冷。"},
  {id:338, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒脉微而厥，至七八日肤冷，其人躁无暂安时者，此为脏厥，非蛔厥也。蛔厥者，其人当吐蛔。今病者静而复时烦者，此为脏寒，蛔上入其膈，故烦，须臾复止，得食而呕又烦者，蛔闻食臭出，其人常自吐蛔。蛔厥者，乌梅丸主之。又主久利。", explain:"伤寒脉微而厥、肤冷、躁无暂安是脏厥；蛔厥者当吐蛔，静而复烦、得食而呕，用乌梅丸，又治久利。"},
  {id:339, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒热少厥微，指头寒，嘿嘿不欲食，烦躁。数日小便利，色白者，此热除也，欲得食，其病为愈。若厥而呕，胸胁烦满者，其后必便血。", explain:"伤寒热少厥微、指头寒、不欲食、烦躁，数日小便利色白是热除欲愈；若厥而呕、胸胁烦满，其后必便血。"},
  {id:340, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"病者手足厥冷，言我不结胸，小腹满，按之痛者，此冷结在膀胱关元也。", explain:"手足厥冷、不结胸、小腹满按之痛，是冷结在膀胱关元。"},
  {id:341, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒发热四日，厥反三日，复热四日，厥少热多者，其病当愈。四日至七日，热不除者，必便脓血。", explain:"伤寒发热四日、厥三日、复热四日，厥少热多当愈；热久不除则便脓血。"},
  {id:342, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒厥四日，热反三日，复厥五日，其病为进。寒多热少，阳气退，故为进也。", explain:"伤寒厥四日、热三日、复厥五日，寒多热少、阳气退，病为进展。"},
  {id:343, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒六七日，脉微，手足厥冷，烦躁，灸厥阴。厥不还者，死。", explain:"伤寒六七日脉微、手足厥冷、烦躁，灸厥阴；厥不回者死。"},
  {id:344, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒发热，下利厥逆，躁不得卧者，死。", explain:"伤寒发热、下利厥逆、躁不得卧的，死证。"},
  {id:345, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒发热，下利至甚，厥不止者，死。", explain:"伤寒发热、下利至甚、厥不止的，死证。"},
  {id:346, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒六七日不利，便发热而利，其人汗出不止者，死。有阴无阳故也。", explain:"伤寒六七日不下利，反发热而利、汗出不止，是阴盛无阳，死证。"},
  {id:347, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒五六日，不结胸，腹濡，脉虚复厥者，不可下，此亡血，下之死。", explain:"伤寒五六日不结胸、腹软、脉虚而厥，是亡血，不可下，下之死。"},
  {id:348, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"发热而厥，七日下利者，为难治。", explain:"发热而厥、七日下利的，难治。"},
  {id:349, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒脉促，手足厥逆，可灸之。", explain:"伤寒脉促、手足厥逆的，可以灸之。"},
  {id:350, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒脉滑而厥者，里有热，白虎汤主之。", explain:"伤寒脉滑而厥，是里有热，用白虎汤。"},
  {id:351, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"手足厥寒，脉细欲绝者，当归四逆汤主之。", explain:"手足厥寒、脉细欲绝的，用当归四逆汤。"},
  {id:352, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"若其人内有久寒者，宜当归四逆加吴茱萸生姜汤。", explain:"若内有久寒的，宜当归四逆加吴茱萸生姜汤。"},
  {id:353, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"大汗出，热不去，内拘急，四肢疼，又下利厥逆而恶寒者，四逆汤主之。", explain:"大汗出、热不去、内拘急、四肢疼、下利厥逆恶寒的，用四逆汤。"},
  {id:354, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"大汗，若大下利而厥冷者，四逆汤主之。", explain:"大汗或大下利而厥冷的，用四逆汤。"},
  {id:355, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜瓜蒂散。", explain:"手足厥冷、脉乍紧、心下满而烦、饥不能食，是邪结胸中，当吐，宜瓜蒂散。"},
  {id:356, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒厥而心下悸，宜先治水，当服茯苓甘草汤，却治其厥。不尔，水渍入胃，必作利也。", explain:"伤寒厥而心下悸，应先治水，服茯苓甘草汤，再治其厥，否则水渍入胃必作利。"},
  {id:357, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，喉咽不利，唾脓血，泄利不止者，为难治，麻黄升麻汤主之。", explain:"伤寒六七日大下后，寸脉沉迟、手足厥逆、下部脉不至、咽喉不利、唾脓血、泄利不止的难治，用麻黄升麻汤。"},
  {id:358, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒四五日，腹中痛，若转气下趣少腹者，此欲自利也。", explain:"伤寒四五日腹中痛，若气向下转至少腹，是欲下利。"},
  {id:359, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒本自寒下，医复吐下之，寒格更逆吐下，若食入口即吐，干姜黄芩黄连人参汤主之。", explain:"伤寒本自寒下，医又吐下，寒格上逆、食入口即吐的，用干姜黄芩黄连人参汤。"},
  {id:360, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利有微热而渴，脉弱者，今自愈。", explain:"下利微热而渴、脉弱的，将自愈。"},
  {id:361, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利脉数，有微热汗出，今自愈；设复紧，为未解。", explain:"下利脉数、微热汗出，将自愈；若脉复紧则未解。"},
  {id:362, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利，手足厥冷，无脉者，灸之。不温，若脉不还，反微喘者，死。少阴负趺阳者，为顺也。", explain:"下利手足厥冷、无脉，灸之；不温、脉不还反微喘者死；少阴脉弱于趺阳为顺。"},
  {id:363, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利，寸脉反浮数，尺中自涩者，必清脓血。", explain:"下利寸脉浮数、尺脉涩的，必便脓血。"},
  {id:364, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利清谷，不可攻表，汗出必胀满。", explain:"下利清谷不可攻表，发汗必腹胀满。"},
  {id:365, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热不死。", explain:"下利脉沉弦者下重，脉大者未止，脉微弱数者欲自止，虽发热不死。"},
  {id:366, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，必郁冒汗出而解，病人必微厥。所以然者，其面戴阳，下虚故也。", explain:"下利脉沉迟、面少赤、身微热、下利清谷，是戴阳下虚，必郁冒汗出而解、微厥。"},
  {id:367, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利脉数而渴者，今自愈。设不差，必清脓血，以有热故也。", explain:"下利脉数而渴者将自愈；若不愈必便脓血，因有热。"},
  {id:368, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利后脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。", explain:"下利后脉绝、手足厥冷，一昼夜后脉还、手足温者生，脉不还者死。"},
  {id:369, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒下利日十余行，脉反实者，死。", explain:"伤寒下利日十余行、脉反实的，死证。"},
  {id:370, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利清谷，里寒外热，汗出而厥者，通脉四逆汤主之。", explain:"下利清谷、里寒外热、汗出而厥的，用通脉四逆汤。"},
  {id:371, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"热利下重者，白头翁汤主之。", explain:"热利下重的，用白头翁汤。"},
  {id:372, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利腹胀满，身体疼痛者，先温其里，乃攻其表。温里宜四逆汤，攻表宜桂枝汤。", explain:"下利腹胀满、身体疼痛，先温里用四逆汤，后攻表用桂枝汤。"},
  {id:373, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利欲饮水者，以有热故也，白头翁汤主之。", explain:"下利欲饮水的，因有热，用白头翁汤。"},
  {id:374, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利谵语者，有燥屎也，宜小承气汤。", explain:"下利而谵语，是有燥屎，宜小承气汤。"},
  {id:375, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"下利后更烦，按之心下濡者，为虚烦也，宜栀子豉汤。", explain:"下利后更烦、按之心下软，是虚烦，宜栀子豉汤。"},
  {id:376, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"呕家有痈脓者，不可治呕，脓尽自愈。", explain:"呕家有痈脓的不可止呕，脓尽自愈。"},
  {id:377, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"呕而脉弱，小便复利，身有微热，见厥者难治，四逆汤主之。", explain:"呕而脉弱、小便复利、身微热、见厥的难治，用四逆汤。"},
  {id:378, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"干呕，吐涎沫，头痛者，吴茱萸汤主之。", explain:"干呕、吐涎沫、头痛的，用吴茱萸汤。"},
  {id:379, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"呕而发热者，小柴胡汤主之。", explain:"呕而发热的，用小柴胡汤。"},
  {id:380, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒大吐大下之，极虚，复极汗者，其人外气怫郁，复与之水以发其汗，因得哕。所以然者，胃中寒冷故也。", explain:"伤寒大吐大下后极虚、又极汗，胃中寒冷，再与水发汗则哕。"},
  {id:381, chapter:"辨厥阴病脉证并治", category:"厥阴病", text:"伤寒哕而腹满，视其前后，知何部不利，利之即愈。", explain:"伤寒哕而腹满，看其大小便何部不利，通利之即愈。"},

  // ========== 辨霍乱病脉证并治 第 382-391 条 ==========
  {id:382, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"问曰：病有霍乱者何？答曰：呕吐而利，此名霍乱。", explain:"呕吐而下利并作的，叫霍乱。"},
  {id:383, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"问曰：病发热头痛，身疼恶寒，吐利者，此属何病？答曰：此名霍乱。霍乱自吐下，又利止，复更发热也。", explain:"发热头痛、身疼恶寒、吐利的，叫霍乱；吐利止后又会发热。"},
  {id:384, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"伤寒，其脉微涩者，本是霍乱，今是伤寒，却四五日至阴经上，转入阴必利，本呕下利者，不可治也。欲似大便，而反失气，仍不利者，此属阳明也，便必硬，十三日愈。所以然者，经尽故也。下利后当便硬，硬则能食者愈。今反不能食，到后经中，颇能食，复过一经能食，过之一日当愈；不愈者，不属阳明也。", explain:"伤寒脉微涩，本是霍乱转来；本呕下利者难治；若欲大便反失气而不利属阳明，便必硬，十三日经尽而愈。"},
  {id:385, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"恶寒脉微而复利，利止亡血也，四逆加人参汤主之。", explain:"恶寒脉微而复利、利止亡血的，用四逆加人参汤。"},
  {id:386, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"霍乱，头痛发热，身疼痛，热多欲饮水者，五苓散主之；寒多不用水者，理中丸主之。", explain:"霍乱头痛发热、身痛、热多欲饮水的用五苓散，寒多不饮水的用理中丸。"},
  {id:387, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"吐利止而身痛不休者，当消息和解其外，宜桂枝汤小和之。", explain:"吐利止而身痛不止的，当调和其外，宜桂枝汤小和之。"},
  {id:388, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"吐利汗出，发热恶寒，四肢拘急，手足厥冷者，四逆汤主之。", explain:"吐利汗出、发热恶寒、四肢拘急、手足厥冷的，用四逆汤。"},
  {id:389, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"既吐且利，小便复利而大汗出，下利清谷，内寒外热，脉微欲绝者，四逆汤主之。", explain:"既吐又利、小便复利、大汗出、下利清谷、内寒外热、脉微欲绝的，用四逆汤。"},
  {id:390, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，通脉四逆加猪胆汁汤主之。", explain:"吐利已止、汗出而厥、四肢拘急不解、脉微欲绝的，用通脉四逆加猪胆汁汤。"},
  {id:391, chapter:"辨霍乱病脉证并治", category:"霍乱病", text:"吐利发汗，脉平，小烦者，以新虚不胜谷气故也。", explain:"吐利发汗后脉平、小烦，是新虚不胜谷气之故。"},

  // ========== 辨阴阳易差后劳复病脉证并治 第 392-398 条 ==========
  {id:392, chapter:"辨阴阳易差后劳复病脉证并治", category:"阴阳易差后劳复", text:"伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。", explain:"伤寒阴阳易之病，身体重、少气、少腹里急、引阴中拘挛、热上冲胸、头重、眼生花、膝胫拘急的，用烧裈散。"},
  {id:393, chapter:"辨阴阳易差后劳复病脉证并治", category:"阴阳易差后劳复", text:"大病差后劳复者，枳实栀子豉汤主之。", explain:"大病愈后因劳累而复发的，用枳实栀子豉汤。"},
  {id:394, chapter:"辨阴阳易差后劳复病脉证并治", category:"阴阳易差后劳复", text:"伤寒差以后，更发热，小柴胡汤主之。脉浮者，以汗解之；脉沉实者，以下解之。", explain:"伤寒愈后又发热的用小柴胡汤；脉浮的汗解，脉沉实的下解。"},
  {id:395, chapter:"辨阴阳易差后劳复病脉证并治", category:"阴阳易差后劳复", text:"大病差后，从腰以下有水气者，牡蛎泽泻散主之。", explain:"大病愈后腰以下有水气的，用牡蛎泽泻散。"},
  {id:396, chapter:"辨阴阳易差后劳复病脉证并治", category:"阴阳易差后劳复", text:"大病差后，喜唾，久不了了，胸上有寒，当以丸药温之，宜理中丸。", explain:"大病愈后喜唾、久而不止，是胸上有寒，当用理中丸温之。"},
  {id:397, chapter:"辨阴阳易差后劳复病脉证并治", category:"阴阳易差后劳复", text:"伤寒解后，虚羸少气，气逆欲吐，竹叶石膏汤主之。", explain:"伤寒解后虚羸少气、气逆欲吐的，用竹叶石膏汤。"},
  {id:398, chapter:"辨阴阳易差后劳复病脉证并治", category:"阴阳易差后劳复", text:"病人脉已解，而日暮微烦，以病新差，人强与谷，脾胃气尚弱，不能消谷，故令微烦。损谷则愈。", explain:"病愈后日暮微烦，是脾胃气尚弱、不能消谷，减少饮食即愈。"}
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = SHLH_DATA;
}
